// Combine the scored alert with the dedupe result and decide what happens to it
const alert = $('Score Alert').item.json;
const duplicate = !$json.is_new;
const action = duplicate ? 'suppressed' : alert.severity === 'low' ? 'logged' : 'notified';

return { json: {
  ...alert,
  duplicate,
  action,
  // Row for the audit log (keys match the alert_log columns)
  logRecord: {
    alert_id: alert.alertId, alert_time: alert.time, rule_id: alert.ruleId, level: alert.level,
    description: alert.description, agent: alert.agent, srcip: alert.srcip, srcuser: alert.srcuser,
    country: alert.country, isp: alert.isp, mitre: alert.mitre, score: alert.score,
    severity: alert.severity, reasons: alert.reasons, action,
  },
} };
